target.css:
:root {
  --ink: #202a39;
  --muted: #697386;
  --card: #ffffff;
  --line: #dce3ec;
  --lavender: #ebe5ff;
  --violet: #6854c5;
  --violet-deep: #493a9c;
  --mint: #dff5eb;
  --mint-ink: #21795b;
}

.cycle-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.machine-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--lavender);
  color: var(--violet-deep);
  font-size: 15px;
  font-weight: 800;
}

.title-block {
  flex: 1;
}

.eyebrow,
.title-block h1,
.time-readout p,
.card-footer p {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.title-block h1 {
  font-size: 19px;
  line-height: 1.2;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--mint-ink);
  font-size: 12px;
  font-weight: 800;
}

.cycle-summary {
  display: grid;
  grid-template-columns: 128px 1fr;
  gap: 16px;
  padding: 15px 0;
}

.time-readout {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 10px 13px;
  border-radius: 13px;
  background: var(--lavender);
}

.time-readout strong {
  color: var(--violet-deep);
  font-size: 28px;
  line-height: 1;
}

.time-readout strong span {
  font-size: 14px;
}

.time-readout p {
  margin-top: 4px;
  color: var(--violet);
  font-size: 12px;
  font-weight: 700;
}

.details-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.details-list li {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
}

.details-list span {
  color: var(--muted);
  font-size: 11px;
}

.details-list b {
  font-size: 12px;
  line-height: 1.25;
}

.progress-area {
  padding: 12px 0 14px;
  border-top: 1px solid var(--line);
}

.progress-label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 7px;
  color: var(--muted);
  font-size: 12px;
}

.progress-label b {
  color: var(--violet-deep);
}

.track {
  overflow: hidden;
  height: 7px;
  border-radius: 999px;
  background: var(--lavender);
}

.track span {
  display: block;
  width: 62%;
  height: 100%;
  border-radius: inherit;
  background: var(--violet);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-footer p {
  color: var(--muted);
  font-size: 12px;
}

.card-footer button {
  padding: 8px 12px;
  border: 0;
  border-radius: 9px;
  background: var(--violet-deep);
  color: var(--card);
  font-size: 12px;
  font-weight: 800;
}

